 "model": {
  "variables": [
   {
    "name": "employee_hectares",
    "lower": 0.0,
    "upper": null,
    "integer": false
   },
   {
    "name": "upick_hectares",
    "lower": 0.0,
    "upper": null,
    "integer": false
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "employee_hectares",
     "coef": 60.0
    },
    {
     "var": "upick_hectares",
     "coef": 45.0
    }
   ]
  },
  "constraints": [
   {
    "name": "land",
    "terms": [
     {
      "var": "employee_hectares",
      "coef": 1.0
     },
     {
      "var": "upick_hectares",
      "coef": 1.0
     }
    ],
    "sense": "<=",
    "rhs": 225.0
   },
   {
    "name": "picking_minutes",
    "terms": [
     {
      "var": "employee_hectares",
      "coef": 30.0
     },
     {
      "var": "upick_hectares",
      "coef": 20.0
     }
    ],
    "sense": "<=",
    "rhs": 8000.0
   },
   {
    "name": "waste",
